  1→/**
  2→ * Tests for discriminative token extraction.
  3→ *
  4→ * Every case here defends one claim: that finding this string in the work has
  5→ * no explanation other than the asset. A token that fails any of them turns a
  6→ * "used" judgement into a coincidence.
  7→ */
  8→
  9→import { test } from "node:test";
 10→import assert from "node:assert/strict";
 11→import { readFileSync } from "node:fs";
 12→
 13→import {
 14→  extractTokens,
 15→  screen,
 16→  discriminativeTokens,
 17→  findTokens,
 18→  systemPromptsFromCapture,
 19→  poolCorpus,
 20→  ownMetadata,
 21→} from "./extract-tokens.mjs";
 22→
 23→const tokenOf = (list, token) => list.find((t) => t.token === token);
 24→
 25→// ── derivability: a prior on the shape ────────────────────────────
 26→
 27→test("a loopback address proves nothing — everyone writes it from memory", () => {
 28→  assert.equal(tokenOf(extractTokens("connect to 127.0.0.1:8096"), "127.0.0.1").derivable, true);
 29→});
