  1→/**
  2→ * Tests for discriminative token extraction.
  3→ *
  4→ * Every case here defends one claim: that finding this string in the work has
  5→ * no explanation other than the asset. A token that fails any of them turns a
  6→ * "used" judgement into a coincidence.
  7→ */
  8→
  9→import { test } from "node:test";
 10→import assert from "node:assert/strict";
 11→import { readFileSync } from "node:fs";
 12→
 13→import {
 14→  extractTokens,
 15→  screen,
 16→  discriminativeTokens,
 17→  findTokens,
 18→  systemPromptsFromCapture,
 19→  poolCorpus,
 20→  ownMetadata,
 21→} from "./extract-tokens.mjs";
 22→
 23→const tokenOf = (list, token) => list.find((t) => t.token === token);
 24→
 25→// ── derivability: a prior on the shape ────────────────────────────
 26→
 27→test("a loopback address proves nothing — everyone writes it from memory", () => {
 28→  assert.equal(tokenOf(extractTokens("connect to 127.0.0.1:8096"), "127.0.0.1").derivable, true);
 29→});
 30→
 31→test("a private-range address is not guessable and counts", () => {
 32→  // 10.244.7.19 is as unguessable as a public address. Treating "private" as
 33→  // "well known" would throw away the only usable token in the pair.
 34→  assert.equal(tokenOf(extractTokens("connect to 10.244.7.19:8096"), "10.244.7.19").derivable, false);
 35→});
 36→
 37→test("a well-known port is derivable, an arbitrary one is not", () => {
 38→  const t = extractTokens("try :443 then :47318");
 39→  assert.equal(tokenOf(t, "443").derivable, true);
 40→  assert.equal(tokenOf(t, "47318").derivable, false);
 41→});
 42→
 43→test("prefixed ids are never derivable", () => {
 44→  assert.equal(tokenOf(extractTokens("skill_id skl-gWTY69V4tFw7"), "skl-gWTY69V4tFw7").derivable, false);
 45→});
 46→
 47→test("an invalid octet is not read as an address", () => {
 48→  assert.equal(tokenOf(extractTokens("version 10.244.7.999"), "10.244.7.999"), undefined);
 49→});
 50→
 51→// ── screening: the filter that actually holds ─────────────────────
 52→
 53→test("a token already in the injected system prompt is rejected", () => {
 54→  // The load-bearing case. The <skill_tools> block names the bridge endpoint on
 55→  // every turn, so an asset documenting it adds nothing the model did not have.
 56→  const screened = screen(extractTokens("use http://127.0.0.1:8096/skill-bridge/v3/skill/search"), {
 57→    "system prompt": "path: http://127.0.0.1:8096/skill-bridge/v3/skill/search",
 58→  });
 59→  const ip = tokenOf(screened, "127.0.0.1");
 60→  assert.equal(ip.discriminative, false);
 61→  assert.deepEqual(ip.blocked_by, ["system prompt"]);
 62→});
 63→
 64→test("a token shared with another candidate asset is rejected", () => {
 65→  // Constraint (c). Seeing it in the work cannot say which of the two was read.
 66→  const screened = screen(extractTokens("host 10.244.7.19"), { "sibling asset": "also mentions 10.244.7.19" });
 67→  assert.equal(tokenOf(screened, "10.244.7.19").discriminative, false);
 68→});
 69→
 70→test("a rejection names the source that killed it", () => {
 71→  // A count of rejections is useless; the scenario can only be repaired if you
 72→  // know which corpus the token leaked from.
 73→  const screened = screen(extractTokens("host 10.9.8.7"), {
 74→    "task description": "deploy to 10.9.8.7",
 75→    "pre-change files": "nothing relevant",
 76→  });
 77→  assert.deepEqual(tokenOf(screened, "10.9.8.7").blocked_by, ["task description"]);
 78→});
 79→
 80→test("an asset's own name is not evidence that its body was read", () => {
 81→  // The name is what the candidate listing shows. A model that writes it has
 82→  // demonstrated recall, not use.
 83→  const asset = [
 84→    "---",
 85→    "name: eval-bridge-endpoint-b",
 86→    "description: Where to reach the bridge.",
 87→    "---",
 88→    "Send requests to eval-bridge-endpoint-b with trace bt-testonly-rightval.",
 89→  ].join("\n");
 90→
 91→  assert.match(ownMetadata(asset), /eval-bridge-endpoint-b/);
 92→  const screened = screen(extractTokens(asset), { "own name/description": ownMetadata(asset) });
 93→  assert.equal(tokenOf(screened, "eval-bridge-endpoint-b").discriminative, false);
 94→  assert.equal(tokenOf(screened, "bt-testonly-rightval").discriminative, true);
 95→});
 96→
 97→// ── corpora ───────────────────────────────────────────────────────
 98→
 99→test("only system messages of requests are read as injected context", () => {
100→  // A model's own reply is not context it was given. Counting it would let the
101→  // model screen out its own tokens.
102→  const capture = [
103→    JSON.stringify({ event: "http.request", body: { json: { messages: [
104→      { role: "system", content: "endpoint 127.0.0.1:8096" },
105→      { role: "assistant", content: "I will use 10.9.8.7" },
106→    ] } } }),
107→    JSON.stringify({ event: "http.response", body: { json: { choices: [] } } }),
108→  ].join("\n");
109→
110→  const corpus = systemPromptsFromCapture(capture);
111→  assert.match(corpus, /127\.0\.0\.1/);
112→  assert.doesNotMatch(corpus, /10\.9\.8\.7/);
113→});
114→
115→test("the pool corpus excludes the assets under test", () => {
116→  const snapshot = { assets: [
117→    { asset_id: "skl-A", name: "under-test", description: "uses 10.9.8.7" },
118→    { asset_id: "skl-B", name: "other", description: "uses 10.1.1.2" },
119→  ] };
120→  const corpus = poolCorpus(snapshot, ["skl-A"]);
121→  assert.doesNotMatch(corpus, /10\.9\.8\.7/);
122→  assert.match(corpus, /10\.1\.1\.2/);
123→});
124→
125→test("a task description carrying a discriminative token is caught", () => {
126→  // P4-1b's check: a task description that names the answer makes every later
127→  // "used" judgement meaningless.
128→  const tokens = discriminativeTokens("send x-team-trace: bt-testwrong to the bridge", {});
129→  assert.deepEqual(findTokens("carry the trace bt-testwrong", tokens).map((t) => t.token), ["bt-testwrong"]);
130→  assert.deepEqual(findTokens("fetch a team skill and follow it", tokens), []);
131→});
132→
133→// ── the mainline pair ─────────────────────────────────────────────
134→
135→test("方案 2 之后,资产源文件是占位符,正文里不再含判别值", () => {
136→  // v4(2026-09-10):判别值明文只在 Core 的资产正文里,仓库的 assets/*.md 是占位符。
137→  // 所以对本地正文抽取,应当抽不到 bt- 判别值——它不在磁盘的仓库树里,这正是方案 2 的
138→  // 目的。判别值的发现改由 resolve-tokens.mjs 用作者密钥从 Core 取回。
139→  const wrong = readFileSync("evaluation/tasks/bridge-addr/assets/wrong.md", "utf8");
140→  const right = readFileSync("evaluation/tasks/bridge-addr/assets/right.md", "utf8");
141→  assert.match(wrong, /x-team-trace:\s*<[^>]*>/, "本地是占位符");
142→  assert.match(right, /x-team-trace:\s*<[^>]*>/, "本地是占位符");
143→  assert.ok(!/bt-[a-z0-9]{6,}/.test(wrong), "占位符里没有 bt- 明文");
144→  assert.ok(!/bt-[a-z0-9]{6,}/.test(right), "占位符里没有 bt- 明文");
145→
146→  const systemPrompt = systemPromptsFromCapture(
147→    readFileSync("evaluation/gate0/artifacts/gate0-threechannel-capture.jsonl", "utf8"),
148→  );
149→  const forAsset = (text, sibling) => discriminativeTokens(text, {
150→    "system prompt": systemPrompt, sibling, "own name/description": ownMetadata(text),
151→  }).map((t) => t.token);
152→  assert.deepEqual(forAsset(wrong, right), [], "占位符正文抽不到判别值");
153→  assert.deepEqual(forAsset(right, wrong), [], "占位符正文抽不到判别值");
154→});
155→
156→test("地址不再算判别性 token,哪怕语料里一次都没出现过", () => {
157→  const asset = "Send requests to http://10.244.7.19:8096/skill-bridge/v3/skill/search";
158→  const screened = screen(extractTokens(asset), {});
159→  const ip = tokenOf(screened, "10.244.7.19");
160→  assert.equal(ip.discriminative, false, "地址写在部署配置里,有进程在监听,shell 就能拿到");
161→  assert.equal(ip.derivable_from_deployment, true);
162→  assert.deepEqual(ip.blocked_by, [], "它不是被语料挡下的,是被形状挡下的——两者理由不同");
163→});
164→
165→test("the right-address asset cannot document the endpoint already in the prompt", () => {
166→  // Regression on the finding that forced the rewrite: right.md originally read
167→  // 127.0.0.1:8096, which is in <skill_tools> verbatim on every turn. It had no
168→  // discriminative token at all, so "the model used the right asset" would have
169→  // been unprovable in the direction the demo depends on.
170→  const systemPrompt = systemPromptsFromCapture(
171→    readFileSync("evaluation/gate0/artifacts/gate0-threechannel-capture.jsonl", "utf8"),
172→  );
173→  // v3 之后这条要连追踪值一起去掉才成立:追踪头正是为了让"资产被读过"不再依赖
174→  // 地址而加的。去掉它、再把地址换回提示词里已有的那个,资产就退回当初那个状态——
175→  // 一个判别性 token 都没有,"模型用了对的资产"无从证明。
176→  const original = readFileSync("evaluation/tasks/bridge-addr/assets/right.md", "utf8")
177→    .replace("127.0.0.1:47318", "127.0.0.1:8096")
178→    .replace(/^ *x-team-trace: .*$/m, "")
179→    .replace(/## About the trace header[\s\S]*?\n## /m, "## ");
180→  // The sibling belongs in the corpus: constraint (c) is about the pool these
181→  // two are in. Without it the shared task marker survives screening, and a
182→  // value both assets carry cannot say which one was followed.
183→  const sibling = readFileSync("evaluation/tasks/bridge-addr/assets/wrong.md", "utf8");
184→
185→  assert.deepEqual(
186→    discriminativeTokens(original, {
187→      "system prompt": systemPrompt,
188→      sibling,
189→      "own name/description": ownMetadata(original),
190→    }),
191→    [],
192→  );
193→});
194→
195→test("the two assets differ only in the address and the trace value", () => {
196→  // Any further difference gives attribution a second explanation. The trace
197→  // value joined the address as a deliberate difference in v3 (2026-09-09);
198→  // everything else still has to match byte for byte.
199→  const strip = (s) => s.replace(/eval-bridge-endpoint-[ab]/g, "NAME")
200→    .replace(/(10\.244\.7\.19:8096|127\.0\.0\.1:47318)/g, "ADDR")
201→    .replace(/bt-[a-z0-9]+/g, "TRACE");
202→  assert.equal(
203→    strip(readFileSync("evaluation/tasks/bridge-addr/assets/wrong.md", "utf8")),
204→    strip(readFileSync("evaluation/tasks/bridge-addr/assets/right.md", "utf8")),
205→  );
206→});
